class TenantConfigAcrValuesSupportedAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAcrValuesSupported returns null on a freshly created holder.
     */
    public function testAcrValuesSupportedNotAssignedByDefault(): void
    {
        // Arrange
